const insertBefore = (source, token, value, from = 0) => {
  const i = source.indexOf(token, from);
  if (i < 0) throw new Error('Missing insertion point: ' + token);
  return source.slice(0, i) + value + source.slice(i);
};
html = insertBefore(html, '</style>', '/* ui-refresh-v2 */' + styles[0]);
html = insertBefore(html, '&lt;/style&gt;', '/* ui-refresh-v2 */' + styles[1]);
const first = html.indexOf('&lt;/style&gt;');
html = insertBefore(html, '&lt;/style&gt;', '/* ui-refresh-v2 */' + styles[2], first + 1);
fs.writeFileSync(file, html, 'utf8');
console.log('Applied visual-only CSS refresh to launcher, drone app, and robot app.');
